import {
  useSignal,
  useStore,
  useTask$,
  useVisibleTask$,
  isServer,
  type Signal,
  type ReadonlySignal,
  type QRL,
} from "@builder.io/qwik";

/**
 * Returns a read-only signal that mirrors `source.value`, but updates are debounced by `delayMs`.
 */
export function useDebouncedSignal<T>(
  source: Signal<T>,
  delayMs: number
): ReadonlySignal<T> {
  const debounced = useSignal<T>(source.value);

  useTask$(({ track, cleanup }) => {
    const value = track(() => source.value);

    if (isServer) {
      debounced.value = value;
      return;
    }

    if (debounced.value === value) {
      return;
    }

    const id = setTimeout(() => {
      debounced.value = value;
    }, delayMs);

    cleanup(() => clearTimeout(id));
  });

  return debounced;
}

/**
 * Returns a read-only signal implementing leading + trailing edge throttling.
 */
export function useThrottledSignal<T>(
  source: Signal<T>,
  intervalMs: number
): ReadonlySignal<T> {
  const throttled = useSignal<T>(source.value);

  const state = useStore({
    lastApplied: 0,
    hasTrailing: false,
    trailingValue: undefined as T | undefined,
  });

  useTask$(({ track, cleanup }) => {
    const value = track(() => source.value);

    if (isServer) {
      throttled.value = value;
      return;
    }

    const now = Date.now();
    const elapsed = now - state.lastApplied;

    if (elapsed >= intervalMs) {
      // Leading edge: update immediately
      throttled.value = value;
      state.lastApplied = now;
      state.hasTrailing = false;
      state.trailingValue = undefined;
    } else {
      // Within window: save as trailing value and schedule timer for the remaining time
      state.trailingValue = value;
      state.hasTrailing = true;

      const remaining = intervalMs - elapsed;
      const id = setTimeout(() => {
        if (state.hasTrailing) {
          throttled.value = state.trailingValue as T;
          state.lastApplied = Date.now();
          state.hasTrailing = false;
          state.trailingValue = undefined;
        }
      }, remaining);

      cleanup(() => clearTimeout(id));
    }
  });

  return throttled;
}

/**
 * Returns a read-only signal holding the value `source` had immediately before its most recent change.
 */
export function usePrevious<T>(
  source: Signal<T>
): ReadonlySignal<T | undefined> {
  const previous = useSignal<T | undefined>(undefined);
  const current = useSignal<T>(source.value);

  useTask$(({ track }) => {
    const value = track(() => source.value);

    if (value !== current.value) {
      previous.value = current.value;
      current.value = value;
    }
  });

  return previous;
}

/**
 * Invokes a serializable QRL callback every `ms` milliseconds while `enabled.value` is true.
 */
export function useInterval(
  callback: QRL<() => void>,
  ms: number,
  enabled: Signal<boolean>
): void {
  useVisibleTask$(({ track, cleanup }) => {
    const isEnabled = track(() => enabled.value);

    if (!isEnabled) {
      return;
    }

    const id = setInterval(() => {
      callback();
    }, ms);

    cleanup(() => clearInterval(id));
  });
}

import { component$, useSignal, $ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";
import {
  useDebouncedSignal,
  useThrottledSignal,
  usePrevious,
  useInterval,
} from "../hooks/signals";

export default component$(() => {
  const debounceInput = useSignal("");
  const debounced = useDebouncedSignal(debounceInput, 500);
  const previousDebounced = usePrevious(debounced);

  const throttleInput = useSignal("");
  const throttled = useThrottledSignal(throttleInput, 500);

  const count = useSignal(0);
  const enabled = useSignal(false);

  // We wrap the callback in $() to create a serializable QRL callback.
  const increment = $(() => {
    count.value++;
  });

  useInterval(increment, 200, enabled);

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>Qwik Reactive Timing Hooks Demo</h1>

      <div style={{ marginBottom: "20px" }}>
        <h2>Debounce Section</h2>
        <label>
          Debounce Input:{" "}
          <input
            type="text"
            data-testid="debounce-input"
            value={debounceInput.value}
            onInput$={(ev) => {
              debounceInput.value = (ev.target as HTMLInputElement).value;
            }}
          />
        </label>
        <div>
          Debounced Value:{" "}
          <span data-testid="debounced-value">{debounced.value}</span>
        </div>
        <div>
          Previous Debounced Value:{" "}
          <span data-testid="previous-value">
            {previousDebounced.value !== undefined ? previousDebounced.value : ""}
          </span>
        </div>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Throttle Section</h2>
        <label>
          Throttle Input:{" "}
          <input
            type="text"
            data-testid="throttle-input"
            value={throttleInput.value}
            onInput$={(ev) => {
              throttleInput.value = (ev.target as HTMLInputElement).value;
            }}
          />
        </label>
        <div>
          Throttled Value:{" "}
          <span data-testid="throttled-value">{throttled.value}</span>
        </div>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Interval Section</h2>
        <div>
          Interval Count:{" "}
          <span data-testid="interval-count">{count.value}</span>
        </div>
        <button
          data-testid="toggle-timer"
          onClick$={() => {
            enabled.value = !enabled.value;
          }}
        >
          {enabled.value ? "Disable Timer" : "Enable Timer"}
        </button>
      </div>
    </div>
  );
});

